import{_ as a,o,c as i,ae as t}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"ADR 017: Refinamiento de Lógica AI y Migración Vectorial Cloud","description":"","frontmatter":{},"headers":[],"relativePath":"adr/017-ai-logic-refinements.md","filePath":"adr/017-ai-logic-refinements.md"}'),n={name:"adr/017-ai-logic-refinements.md"};function r(l,e,c,s,d,u){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-017-refinamiento-de-logica-ai-y-migracion-vectorial-cloud" tabindex="-1">ADR 017: Refinamiento de Lógica AI y Migración Vectorial Cloud <a class="header-anchor" href="#adr-017-refinamiento-de-logica-ai-y-migracion-vectorial-cloud" aria-label="Permalink to &quot;ADR 017: Refinamiento de Lógica AI y Migración Vectorial Cloud&quot;">​</a></h1><h2 id="estado" tabindex="-1">Estado <a class="header-anchor" href="#estado" aria-label="Permalink to &quot;Estado&quot;">​</a></h2><p>Aceptado</p><h2 id="fecha" tabindex="-1">Fecha <a class="header-anchor" href="#fecha" aria-label="Permalink to &quot;Fecha&quot;">​</a></h2><p>2026-03-04</p><h2 id="contexto" tabindex="-1">Contexto <a class="header-anchor" href="#contexto" aria-label="Permalink to &quot;Contexto&quot;">​</a></h2><p>El sistema inicial sufría de &quot;ceguera&quot; (no encontraba requisitos en documentos largos), imprecisión en la extracción (confundía texto relleno con requisitos), y dependía de Ollama para la búsqueda vectorial (incompatible con el despliegue en Render).</p><h2 id="decision" tabindex="-1">Decisión <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decisión&quot;">​</a></h2><ol><li><strong>Desbloqueo de Ventana de Contexto</strong>: Se incrementó el límite de caracteres de 25k a <strong>500k</strong> para aprovechar la ventana de 1M tokens de <strong>Gemini 2.5 Flash</strong>.</li><li><strong>Estrategia de Doble Prompt</strong>: <ul><li><strong>Extracción (Input)</strong>: Prompt de &quot;Auditor Legal &amp; Técnico&quot;. Busca imperativos estrictos (&quot;deberá&quot;, &quot;obligatorio&quot;).</li><li><strong>Comparación (Validation)</strong>: Prompt de &quot;Evaluador Senior&quot;. Aplica reglas de equivalencia semántica y cumplimiento positivo (&gt; mínimo es válido).</li></ul></li><li><strong>Migración Vectorial</strong>: Se reemplazó <code>ollama</code> + <code>nomic-embed-text</code> con <strong>Google Genkit (<code>text-embedding-004</code>)</strong> para una arquitectura 100% Cloud-Native.</li><li><strong>Normalización de UI</strong>: Se estandarizó el mapeo de estados (<code>PARTIAL</code> -&gt; Amber) y puntajes de confianza (<code>0-1</code> -&gt; <code>%</code>).</li></ol><h2 id="consecuencias" tabindex="-1">Consecuencias <a class="header-anchor" href="#consecuencias" aria-label="Permalink to &quot;Consecuencias&quot;">​</a></h2><ul><li><strong>Positivas</strong>: <ul><li>Precisión drásticamente mejorada (encuentra evidencia en pág. 20+).</li><li>Eliminación de dependencias locales pesadas (Ollama).</li><li>Experiencia de usuario profesional (Etiquetas en Español, colores consistentes).</li></ul></li><li><strong>Negativas</strong>: <ul><li>Mayor consumo de tokens en Gemini (pero dentro del Free Tier generoso de Google).</li></ul></li></ul>',11)])])}const p=a(n,[["render",r]]);export{g as __pageData,p as default};
